import sys, subprocess, os, json, re
sys.path.insert(0,'stub'); from shred import shred_syntax_spec
opts, pos = shred_syntax_spec[0]
def run(args, stdin_file=None):
    open('f','w').write('x'*10)
    r = subprocess.run(['/usr/bin/shred']+args, capture_output=True, text=True)
    return r.returncode, r.stderr.strip().splitlines()[:1]
good={'Integer':['1','0'], 'Size':['4','1K','2KiB','3kB','1M'], 'Path':['/dev/urandom']}
bad={'Integer':['1k','-1','abc'], 'Size':['x','1e3','-1'], 'Path':['/nonexistent/zzz']}
fails=0
for n in opts:
    spellings=[n.flag]+n.alias
    for s in spellings:
        if s in ('--help','--version'):
            rc,_=run([s]); print(f"{s}: rc={rc}"); fails+= rc!=0; continue
        if n.kind=='Flag':
            rc,err=run([s,'f']); print(f"{s} f: rc={rc} {err}"); fails+= rc!=0
            continue
        vals = n.choices if n.kind=='Selection' else good[n.kind]
        for v in vals:
            forms=[]
            if n.kind=='Selection' and v=='': forms=[[s]]
            elif s.startswith('--'): forms=[[f"{s}={v}"]] + ([] if n.kind=='Selection' else [[s,v]])
            else: forms=[[s,v],[f"{s}{v}"]]
            for fm in forms:
                rc,err=run(fm+['f']); print(f"{' '.join(fm)} f: rc={rc} {err}"); fails+= rc!=0
        if n.kind!='Selection':
            for v in bad[n.kind]:
                rc,err=run([f"{s}={v}" if s.startswith('--') else s, *([] if s.startswith('--') else [v]),'f']); print(f"BAD {s} {v}: rc={rc} {err}"); fails+= rc==0
        else:
            rc,err=run([f"{s}=bogus",'f']); print(f"BAD {s}=bogus rc={rc} {err}"); fails+= rc==0
print("--- operands")
rc,err=run([]); print("no operand rc",rc,err); fails+= rc==0
rc,err=run(['f','f']); print("two operands rc",rc); fails+= rc!=0
print("--- coverage vs --help")
helptxt=subprocess.run(['/usr/bin/shred','--help'],capture_output=True,text=True).stdout
help_opts=set(re.findall(r'(?<![\w-])(--?[a-zA-Z][\w-]*)', helptxt.split('Delete FILE')[0]))
spec_opts={s for n in opts for s in [n.flag]+n.alias}
